mapper.select:
		select py.* from PreVerify py,Portfolio_Hdr ph,VerifyConfig vc,UserRoleGroupMap urgm,Users u where 
        py.portfolio=ph.portfolio and py.verifyconfigID=vc.id and vc.groupID=urgm.groupID and urgm.roleID=u.roleID
       	and u.userid=#{userid} and  py.operationDate>=#{start} and  py.operationDate<=#{end} 

       		and ph.portfolio in

			#{item}
